//image by Amponsah Nii Davidson
//https://www.pexels.com/photo/photo-of-woman-wearing-turban-2523899/

var img, mask, maskInverted, result;
const maxIterations = 20;
var iterationCanvases = [];

/** OPC START **/
OPC.slider('SIZE', 30, 15, 120, 1);
OPC.slider('DISPLACE_X', 10, 0, 30, 1);
OPC.slider('DISPLACE_Y', 10, 0, 30, 1);
OPC.slider('ROTATE', 180, 0, 360, 1);
OPC.slider('SCALE', 1, 0.5, 1.5, 0.01);
OPC.slider('ITERATIONS', 1, 1, 20, 1);
/** OPC END **/
var lastSize, lastDisplaceX, lastDisplaceY, lastIterations, lastRotate, lastScale;

function preload() {
	img = loadImage("https://openprocessing.org/sketch/1250085/files/pexels-amponsah-nii-davidson.png");
}

function setup() {
	createCanvas(img.width, img.height);
	mask = createGraphics(width, height);
	maskInverted = createGraphics(width, height);

	result = createGraphics(width, height);

	for(var i = 0; i < maxIterations; i++){
		iterationCanvases.push(createGraphics(width, height));
	}
}

function draw() {
	if(lastSize != SIZE){
		generateMask();

		//invert mask
		let d = mask.pixelDensity();
		let resolution = (width * d) * (height * d) * 4;
		maskInverted.loadPixels();
		mask.loadPixels();
		for (let i = 0; i < resolution; i += 4) {
			if(mask.pixels[i + 3] == 0) {
				maskInverted.pixels[i + 0] = 0;
				maskInverted.pixels[i + 1] = 0;
				maskInverted.pixels[i + 2] = 0;
				maskInverted.pixels[i + 3] = 255;
			}else{
				maskInverted.pixels[i + 3] = 0;
			}
		}
		maskInverted.updatePixels();
	}

	if(lastSize != SIZE ||
		lastDisplaceX != DISPLACE_X ||
		lastDisplaceY != DISPLACE_Y ||
		lastIterations != ITERATIONS ||
		lastRotate != ROTATE ||
		lastScale != SCALE) {
		lastSize = SIZE;
		lastDisplaceX = DISPLACE_X;
		lastDisplaceY = DISPLACE_Y;
		lastIterations = ITERATIONS;
		lastRotate = ROTATE;
		lastScale = SCALE;

		result.image(img, 0, 0);
		for(var i = 0; i < ITERATIONS; i++){
			var ctx = iterationCanvases[i].drawingContext;
			ctx.save();
			ctx.globalCompositeOperation="destination-atop";
			iterationCanvases[i].image(mask, 0, 0);
			iterationCanvases[i].push();
				iterationCanvases[i].translate(-DISPLACE_X, -DISPLACE_Y);
				iterationCanvases[i].translate(width/2, height/2);
				iterationCanvases[i].scale(SCALE, SCALE);
				iterationCanvases[i].rotate(radians(ROTATE-180));
				iterationCanvases[i].translate(-width/2, -height/2);
				iterationCanvases[i].image(result, 0, 0);
			iterationCanvases[i].pop();
			iterationCanvases[i].image(maskInverted, 0, 0);
			iterationCanvases[i].push();
				iterationCanvases[i].translate(DISPLACE_X, DISPLACE_Y);
				iterationCanvases[i].translate(width/2, height/2);
				iterationCanvases[i].scale(SCALE, SCALE);
				iterationCanvases[i].rotate(radians(ROTATE-180));
				iterationCanvases[i].translate(-width/2, -height/2);
				iterationCanvases[i].image(result, 0, 0);
			iterationCanvases[i].pop();
			ctx.restore();

			result.image(iterationCanvases[i], 0, 0);
		}
	}
	image(result, 0, 0);

	/*
	background(255);
	image(mask, 0, 0);
	image(maskInverted, (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0);
	*/
}

function generateMask() {
	mask.clear();
	mask.fill(0);
	mask.noStroke();
	for (let y = 0; y < height; y+=SIZE) {
		for (let x = 0; x < width; x+=SIZE) {
			var rule = random();
			if(rule < 0.12){
				//0.33x3
				var xx = x + floor(random(3))/3;
				mask.rect(xx, y, SIZE/3, SIZE*3);
			}else if(rule < 0.24){
				//2x0.5
				var yy = y + floor(random(2))/2;
				mask.rect(x, yy, SIZE*2, SIZE/2);
			}else if(rule < 0.5){
				//0.5x2
				var xx = x + floor(random(2))/2;
				mask.rect(xx, y, SIZE/2, SIZE*2);
			}else if(rule < 0.75){
				var subrule = floor(random(3));
				if(subrule == 0){
					//square
					mask.rect(x, y, SIZE, SIZE);
				}else if(subrule == 1){
					//losangle
					mask.beginShape();
						mask.vertex(x+SIZE/2, y);
						mask.vertex(x+SIZE, y+SIZE/2);
						mask.vertex(x+SIZE/2, y+SIZE);
						mask.vertex(x, y+SIZE/2);
					mask.endShape();
				}else if(subrule == 2){
					//small square
					mask.rect(x+SIZE/2, y+SIZE/2, SIZE/2, SIZE/2);
				}
			}else{
				//triangles
				var v = floor(random(4));
				mask.beginShape();
					if(v != 0) mask.vertex(x, y);
					if(v != 1) mask.vertex(x+SIZE, y);
					if(v != 2) mask.vertex(x+SIZE, y+SIZE);
					if(v != 3) mask.vertex(x, y+SIZE);
				mask.endShape();
			}
		}
	}
}

